// GENERERT av scripts/build-landsam-courses.py 2026-09-23 – ikke rediger for hånd.
// Kilde: DBH/HKDIR tabell 308 (karakterer, aggregert) og 208 (emner). Snitt: A=5…F=0, kun bokstavkarakterer.
// DBH skjuler (setter til 0) celler med 1-2 kandidater i karakterfordelingen; dette rammer særlig
// programnivå (mindre celler) og kan gi kunstig lav strykprosent. «skjult» er antall kandidater DBH
// har skjult i akkurat den fordelingen, funnet ved å sammenligne med en uavhengig, mindre skjermet
// sum uten Karakter-oppdeling. «emnenivaa» viser fordelingen for ALLE studenter ved institusjonen som
// tok emnet det året, uavhengig av program – større celler, nærmere de reelle tallene på karakterweb.no.
import type { LandsamLevel } from './landsamAdmissionData';

export interface CourseGradeYear {
  year: number; A: number; B: number; C: number; D: number; E: number; F: number; G: number; H: number;
  total: number; snitt: number | null; strykprosent: number | null; bestattprosent: number | null;
  skjult: number;  // antall kandidater DBH har skjult (skjermet) i denne fordelingen
}
export interface CourseStats {
  emnekode: string; emnenavn: string | null; studiepoeng: number | null;
  years: CourseGradeYear[];              // per program (kan ha skjulte kandidater)
  emnenivaa: CourseGradeYear[];           // ALLE studenter ved institusjonen, uavhengig av program
}
export interface ProgramCourses {
  entryId: string; shortName: string; institusjon: string; isNmbu: boolean;
  dbhInstitusjonskode: string; dbhProgramkoder: string[]; dbhProgramnavn: string;
  courses: CourseStats[];               // sortert på emnekode
}
export interface LandsamCourseGroup { id: string; label: string; level: LandsamLevel; note?: string; programs: ProgramCourses[]; }

